#include "stm32g4xx.h"

void SystemClock_Config_170Mhz(void)
{
    // 1. Configure Flash latency for 170 MHz (4 wait states required at 3.3V for > 150 MHz)
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_4WS;

    // 2. Enable HSI16 (already on by default from reset, but ensure it's ready)
    RCC->CR |= RCC_CR_HSION;
    while (!(RCC->CR & RCC_CR_HSIRDY));

    // 3. Configure PLL: Source = HSI16 (16 MHz)
    // Target SYSCLK = 170 MHz. 
    // VCO input = HSI16 / M = 16 MHz / 4 = 4 MHz (M = 4, range 2.66 to 8 MHz)
    // VCO output = VCO input * N = 4 MHz * 85 = 340 MHz (N between 8 and 127)
    // SYSCLK = VCO output / R = 340 MHz / 2 = 170 MHz (R = 2, 4, 6, or 8)
    RCC->PLLCFGR = (RCC->PLLCFGR & ~(RCC_PLLCFGR_PLLSRC | RCC_PLLCFGR_PLLM | RCC_PLLCFGR_PLLN | RCC_PLLCFGR_PLLR | RCC_PLLCFGR_PLLREN))
                 | (2 << RCC_PLLCFGR_PLLSRC_Pos)   // PLLSRC = HSI16
                 | ((4 - 1) << RCC_PLLCFGR_PLLM_Pos) // M = 4 (value 3 encodes divider 4)
                 | (85 << RCC_PLLCFGR_N_Pos)        // N = 85
                 | (0 << RCC_PLLCFGR_PLLR_Pos)      // R = 2 (value 0 encodes divider 2)
                 | RCC_PLLCFGR_PLLREN;              // Enable PLLCLK output

    // 4. Enable PLL
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY));

    // 5. Select PLL as system clock source
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW) | RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL);

    // AHB, APB1, APB2 prescalers remain at 1 by default (HPRE = 0, PPRE1 = 0, PPRE2 = 0)
}
```

### Explanation
1. **Flash Latency**: At 170 MHz and 3.3 V VDD, the STM32G474 reference manual requires 4 wait states (`FLASH_ACR_LATENCY_4WS`) for safe memory access.
2. **HSI16 Source**: We ensure the 16 MHz internal RC oscillator (`HSI16`) is running and stable.
3. **PLL Calculation**: 
   - Input: 16 MHz (HSI)
   - $M = 4 \rightarrow$ VCO input = 4 MHz
   - $N = 85 \rightarrow$ VCO output = $4 \times 85 = 340$ MHz
   - $R = 2 \rightarrow$ SYSCLK = $340 / 2 = 170$ MHz
4. **Clock Switch**: We enable the PLL, wait for `PLLRDY`, switch the system clock source (`SW = PLL`), and poll `SWS` until the hardware confirms the transition is complete. Prescalers are left at their reset values (div 1).

```c
#include "stm32g4xx.h"

void SystemClock_Config_170Mhz(void)
{
    // 1. Enable Power interface clock to configure the voltage regulator
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;

    // 2. Configure Voltage Scaling Range 1 Normal Mode (R1MODE = 1)
    // Note: R1MODE bit in PWR_CR5 must be configured while VOS is in Range 1 (default after reset).
    // Clearing R1MODE (R1MODE = 0) boosts performance for frequencies > 150 MHz at the cost of higher power.
    // Setting R1MODE (R1MODE = 1) selects Normal mode (saves power).
    PWR->CR5 |= PWR_CR5_R1MODE;

    // 3. Configure Flash latency for 170 MHz (4 wait states required at 3.3V for > 150 MHz)
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_4WS;

    // 4. Enable HSI16 (already on by default from reset, but ensure it's ready)
    RCC->CR |= RCC_CR_HSION;
    while (!(RCC->CR & RCC_CR_HSIRDY));

    // 5. Configure PLL: Source = HSI16 (16 MHz)
    // Target SYSCLK = 170 MHz. 
    // VCO input = HSI16 / M = 16 MHz / 4 = 4 MHz (M = 4)
    // VCO output = VCO input * N = 4 MHz * 85 = 340 MHz (N = 85)
    // SYSCLK = VCO output / R = 340 MHz / 2 = 170 MHz (R = 2)
    RCC->PLLCFGR = (RCC->PLLCFGR & ~(RCC_PLLCFGR_PLLSRC | RCC_PLLCFGR_PLLM | RCC_PLLCFGR_PLLN | RCC_PLLCFGR_PLLR | RCC_PLLCFGR_PLLREN))
                 | (2 << RCC_PLLCFGR_PLLSRC_Pos)   // PLLSRC = HSI16
                 | ((4 - 1) << RCC_PLLCFGR_PLLM_Pos) // M = 4 (value 3 encodes divider 4)
                 | (85 << RCC_PLLCFGR_N_Pos)        // N = 85
                 | (0 << RCC_PLLCFGR_PLLR_Pos)      // R = 2 (value 0 encodes divider 2)
