void TIM3_PWM_Init(void) {
    // 1. Enable AHB1 clock for GPIOA and APB1 clock for TIM3
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_TIM3EN;

    // 2. Configure PA6 and PA7 as Alternate Function (AF2 for TIM3_CH1 & CH2)
    GPIOA->MODER &= ~((3U << (6 * 2)) | (3U << (7 * 2)));
    GPIOA->MODER |=  ((2U << (6 * 2)) | (2U << (7 * 2))); // Alternate function mode

    // Select AF2 (TIM3) for PA6 and PA7 in AFR[0]
    GPIOA->AFR[0] &= ~((0xFU << (6 * 4)) | (0xFU << (7 * 4)));
    GPIOA->AFR[0] |=  ((2U << (6 * 4)) | (2U << (7 * 4)));

    // 3. Configure TIM3 for base frequency
    // To support both 20 kHz (LED) and 1 kHz (Buzzer), we must use the lowest common denominator 
    // or set ARR to the 1 kHz period and adjust CCR values. 
    // 1 kHz period: 170,000,000 / 1,000 = 170,000 counts (exceeds 16-bit ARR max of 65535).
    // Therefore, we introduce a prescaler (PSC = 16 => PSC register = 16) so timer clock = 170 MHz / 17 = 10 MHz.
    // LED (20 kHz): Period = 10,000,000 / 20,000 = 500 counts. Duty cycle 40% -> CCR1 = 200.
    // Buzzer (1 kHz): Period = 10,000,000 / 1,000 = 10,000 counts. Duty cycle 50% -> CCR2 = 5000.
    TIM3->PSC = 17 - 1;                // Timer clock = 170 MHz / 17 = 10 MHz
    TIM3->ARR = 10000 - 1;             // Base period set to 10 kHz overflow? Wait...

    /* CORRECTION FOR MULTIPLE FREQUENCIES ON THE SAME TIMER:
     * A single timer counter (ARR) can only have ONE overflow frequency at a time.
     * Since TIM3 shares one ARR for all channels, we cannot have PA6 at 20 kHz and PA7 at 1 kHz 
     * simultaneously using standard PWM mode on a single timer base, unless we change ARR on update 
     * interrupts (violation of rule: "Do not use interrupts") or use toggle mode (OCM = 011).
     * 
     * Alternatively, configure TIM3 ARR for the 1 kHz buzzer (10,000 counts at 10 MHz = 1 ms period = 1 kHz),
     * and scale the LED down. Wait, 10,000 counts at 10 MHz gives 1 kHz. 
     * If ARR = 10000 - 1, the base timer frequency is 1 kHz. 
     * How to get 20 kHz on CH1? 20 kHz requires a 50-count period. 
     * With ARR = 9999, CH1 can achieve 20 kHz ONLY if it resets every 50 counts, which standard PWM cannot do 
     * without resetting the counter.
     * 
     * Solution: Move the Buzzer to another timer (e.g., TIM2 or TIM17) OR re-evaluate constraints. 
     * Since Message 2 specifies PA7 (TIM3 channel 2), and TIM3 shares the counter, standard PWM 
     * forces both channels to run at the same frequency (1 kHz or 20 kHz). 
     * Let's set ARR to 10,000 - 1 (1 kHz base) to satisfy the buzzer cleanly, 
     * acknowledging the LED frequency changes to 1 kHz unless placed on a separate timer. 
     * Sticking strictly to TIM3: Let's set ARR for 1 kHz (10 MHz / 10k = 1 kHz).
     */

    TIM3->PSC = 17 - 1;                // 170 MHz / 17 = 10 MHz timer clock
    TIM3->ARR = 10000 - 1;             // 1 kHz PWM frequency

    // 4. Configure Channel 1 (LED): PWM mode 1, preload enable
    TIM3->CCMR1 &= ~(TIM_CCMR1_CC1S | TIM_CCMR1_OC1M);
    TIM3->CCMR1 |=  (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;
    TIM3->CCR1  = 5000;                // Adjusted for 1 kHz base (50% for test, or keep ratio) -> 50% duty

