    USART1->BRR = 170000000UL / 115200UL;

    // 8 data bits, no parity, 1 stop bit (defaults in CR1/CR2 are 0 for these)
    // Enable transmitter and receiver before enabling the USART
    USART1->CR1 = USART_CR1_TE | USART_CR1_RE;

