    GPIOA->MODER   |=  (2U << (8 * 2));
    GPIOA->AFR[1]  &= ~(0xFU << ((8 - 8) * 4));
    GPIOA->AFR[1]  |=  (6U << ((8 - 8) * 4));

    // Configure TIM1 time base for 20 kHz at 170 MHz SYSCLK/HCLK/PCLK2
    // f_CK_CNT = 170 MHz / (PSC + 1). Let PSC = 0 -> f_CK_CNT = 170 MHz.
    // ARR = (170,000,000 / 20,000) - 1 = 8500 - 1 = 8499.
    TIM1->PSC       = 0U;
    TIM1->ARR       = 8499U;
    TIM1->CCR1      = 2124U; // 25% duty cycle: 8500 * 0.25 = 2125 counts (CCR1 = 2124)

    // Configure TIM1 Channel 1 as edge-aligned PWM mode 1, active-high output
    TIM1->CCMR1     &= ~(TIM_CCMR1_CC1S | TIM_CCMR1_OC1M);
    TIM1->CCMR1     |=  (TIM_CCMR1_OC1M_1 | TIM_CCMR1_OC1M_2); // PWM mode 1 (110)
    TIM1->CCER      &=  ~(TIM_CCER_CC1P | TIM_CCER_CC1NP);    // Active high (polarity 0)
    TIM1->CCER      |=   TIM_CCER_CC1E;                       // Enable channel 1 output

    // Enable TIM1 main output (MOE) and counter
    TIM1->BDTR      |=   TIM_BDTR_MOE;
    TIM1->CR1       |=   TIM_CR1_CEN;

    // --- Message 2: I2C3 Configuration for BME280 (100 kHz Standard Mode, PC8/PC9) ---
    // Enable GPIOC and I2C3 clocks
    RCC->AHB2ENR  |= RCC_AHB2ENR_GPIOCEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C3EN;

    // Configure PC8 (SCL) and PC9 (SDA) as Alternate Function (AF8 for I2C3)
    // Both pins must be configured in Open-Drain mode with pull-ups.
    GPIOC->MODER   &= ~((3U << (8 * 2)) | (3U << (9 * 2)));
    GPIOC->MODER   |=  ((2U << (8 * 2)) | (2U << (9 * 2))); // Alternate function
    GPIOC->OTYPER  |=  ((1U << 8) | (1U << 9));             // Open-drain output
    GPIOC->PUPDR   &= ~((3U << (8 * 2)) | (3U << (9 * 2)));
    GPIOC->PUPDR   |=  ((1U << (8 * 2)) | (1U << (9 * 2))); // Pull-up enabled
    GPIOC->OSPEEDR |=  ((3U << (8 * 2)) | (3U << (9 * 2))); // Very high speed
    GPIOC->AFR[1]  &= ~((0xFU << ((8 - 8) * 4)) | (0xFU << ((9 - 8) * 4)));
    GPIOC->AFR[1]  |=  ((8U << ((8 - 8) * 4)) | (8U << ((9 - 8) * 4))); // AF8: I2C3_SCL / I2C3_SDA

    // Select PCLK1 as I2C3 clock source (default after reset, but explicitly set CCIPR)
    RCC->CCIPR     &= ~RCC_CCIPR_I2C3SEL;                   // 00: PCLK (170 MHz)

    // Ensure I2C3 is disabled before programming TIMINGR
    I2C3->CR1      &= ~I2C_CR1_PE;

    // Program I2C3 timing for Standard Mode (100 kHz) with fI2CCLK = 170 MHz.
    // Formula / STM32CubeMX parameters for 170 MHz input clock to achieve 100 kHz SCL:
    // PRESC = 16 (value 15), t_PRESC = 17 / 170 MHz = 100 ns
    // SCLL = 0xC7 (199 -> 200 * 100 ns = 20 µs low)
    // SCLH = 0xC3 (195 -> 196 * 100 ns = 19.6 µs high)
    // SDADEL = 0x2, SCLDEL = 0x4
    I2C3->TIMINGR  =  (15U << I2C_TIMINGR_PRESC_Pos) |
                      (4U  << I2C_TIMINGR_SCLDEL_Pos) |
                      (2U  << I2C_TIMINGR_SDADEL_Pos) |
                      (195U << I2C_TIMINGR_SCLH_Pos)  |
                      (199U << I2C_TIMINGR_SCLL_Pos);

    // Enable I2C3 peripheral (controller mode)
    I2C3->CR1      |=  I2C_CR1_PE;

    while (1)
    {
        // Main loop
    }
}
