void SystemClock_Config_170MHz(void)
{
    // 1. Enable Power interface clock
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;

    // 2. Configure Voltage Scaling Range 1 Boost Mode
    // VOS = 0b01 (Range 1) in PWR_CR1
    PWR->CR1 &= ~PWR_CR1_VOS;
    PWR->CR1 |= (1UL << PWR_CR1_VOS_Pos);

    // Clear R1MODE in PWR_CR5 for Boost mode (> 150 MHz up to 170 MHz)
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    // Wait until VOSF flag is cleared in PWR_SR2
    while ((PWR->SR2 & PWR_SR2_VOSF) != 0);

