    FLASH->ACR |= FLASH_ACR_LATENCY_4WS;

    // Enable Instruction cache, Data cache, and Prefetch
    FLASH->ACR |= FLASH_ACR_ICEN | FLASH_ACR_DCEN | FLASH_ACR_PRFTEN;

    // 4. Configure HSI and PLL
    RCC->CR |= RCC_CR_HSION;
    while((RCC->CR & RCC_CR_HSIRDY) == 0);

    // Disable PLL before reconfiguration
    RCC->CR &= ~RCC_CR_PLLON;
    while((RCC->CR & RCC_CR_PLLRDY) != 0);

    // Set PLL Source to HSI, M, N, R dividers
    RCC->PLLCFGR = (2UL << RCC_PLLCFGR_PLLSRC_Pos) |  // PLL source = HSI
                   ((4UL - 1UL) << RCC_PLLCFGR_PLLM_Pos) | // PLLM = 4
                   (85UL << RCC_PLLCFGR_PLLN_Pos) |    // PLLN = 85
                   (0UL << RCC_PLLCFGR_PLLR_Pos) |     // PLLR = 2 (0b00)
                   RCC_PLLCFGR_PLLREN;                 // Enable PLL R output

    // Enable PLL and wait for ready
    RCC->CR |= RCC_CR_PLLON;
    while((RCC->CR & RCC_CR_PLLRDY) == 0);

    // 5. Select PLL as System Clock Source
    RCC->CFGR &= ~RCC_CFGR_SW;
    RCC->CFGR |= RCC_CFGR_SW_PLL;

    // Wait until PLL is selected as system clock
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL);
}
