#include "stm32g4xx.h"

void System_Init(void)
{
    /* ========================================================================= */
    /* 1. CLOCK CONFIGURATION & PERIPHERAL ENABLES                               */
    /* ========================================================================= */
    // Enable clocks for GPIOA, USART1, and TIM3
    RCC->AHB2ENR  |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR  |= RCC_APB2ENR_USART1EN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_TIM3EN;

    /* ========================================================================= */
    /* 2. PIN MULTIPLEXING (GPIO CONFIGURATION)                                  */
    /* ========================================================================= */
    // Configure PA6 to Alternate Function mode (0x2) for TIM3_CH1 (AF2) [STM32G474_Datasheet p. 60, 73]
    GPIOA->MODER &= ~(3U << (6 * 2));
    GPIOA->MODER |=  (2U << (6 * 2));
    GPIOA->OSPEEDR |= (3U << (6 * 2));
    GPIOA->AFR[0] &= ~(0xFU << (6 * 4));
    GPIOA->AFR[0] |=  (0x2U << (6 * 4));

    // Configure PA9 (USART1_TX) and PA10 (USART1_RX) to Alternate Function mode (0x2) (AF7) [STM32G474_Datasheet p. 73]
    GPIOA->MODER &= ~((3U << (9 * 2)) | (3U << (10 * 2)));
    GPIOA->MODER |=  ((2U << (9 * 2)) | (2U << (10 * 2)));
    GPIOA->OSPEEDR |= ((3U << (9 * 2)) | (3U << (10 * 2)));

    // PA9 and PA10 use AF7 in AFR[1] (pins 8-15)
    GPIOA->AFR[1] &= ~((0xFU << ((9 - 8) * 4)) | (0xFU << ((10 - 8) * 4)));
    GPIOA->AFR[1] |=  ((0x7U << ((9 - 8) * 4)) | (0x7U << ((10 - 8) * 4)));

    /* ========================================================================= */
    /* 3. USART1 INITIALIZATION (8N1)                                            */
    /* ========================================================================= */
    // Ensure USART1 is disabled before configuration
    USART1->CR1 &= ~USART_CR1_UE;

    // Configure 8 Data bits, No Parity (default M[1:0] = 00, PCE = 0)
    USART1->CR1 &= ~(USART_CR1_M0 | USART_CR1_M1 | USART_CR1_PCE);

    // Configure 1 Stop bit (default STOP[1:0] = 00)
    USART1->CR2 &= ~USART_CR2_STOP;

    // Set Baud Rate Register (USART_BRR)
    USART1->BRR = 139; [STM32G474_RM0440 p. 1755]

    // Enable Transmitter, Receiver, and USART1
    USART1->CR1 |= (USART_CR1_TE | USART_CR1_RE | USART_CR1_UE);

    /* ========================================================================= */
    /* 4. TIM3 PWM INITIALIZATION (1 kHz, 50% Duty Cycle, Edge-Aligned Mode 1)    */
    /* ========================================================================= */
    TIM3->PSC = 0;
    TIM3->ARR = 16000 - 1;
    TIM3->CCR1 = 8000;

    // Configure Channel 1 as Output (CC1S = 00) and PWM Mode 1 (OC1M = 110)
    TIM3->CCMR1 &= ~TIM_CCMR1_CC1S;
    TIM3->CCMR1 &= ~TIM_CCMR1_OC1M;
    TIM3->CCMR1 |=  (6U << TIM_CCMR1_OC1_Pos);
    TIM3->CCMR1 |= TIM_CCMR1_OC1PE;

    // Configure Output Polarity: Active High (CC1P = 0) and enable Channel 1 Output (CC1E = 1)
    TIM3->CCER &= ~TIM_CCER_CC1P;
    TIM3->CCER |= TIM_CCER_CC1E;

    // Enable TIM3 Counter
    TIM3->CR1 |= TIM_CR1_CEN;
}

int main(void)
{
    System_Init();

    while (1)
    {
        // Infinite loop
    }
}
```

